def clamp(x,lo,hi):
 if lo>hi: raise ValueError("bounds")
 return max(lo,min(x,hi))

def chunks(xs,n):
 if n<=0: raise ValueError("size")
 return [xs[i:i+n] for i in range(0,len(xs),n)]

def runs(xs):
 out=[]
 for x in xs:
  if out and out[-1][0]==x: out[-1]=(x,out[-1][1]+1)
  else: out.append((x,1))
 return out

